def apply_compiled_ball_racket_pair_override(
    model: mujoco.MjModel,
    cfg: Any,
) -> tuple[int, ...]:
    """Apply every compiled ball-racket pair field for an opt-in contract."""

    def first_geom_id(names: tuple[str, ...]) -> int:
        for name in names:
            geom_id = mujoco.mj_name2id(
                model, mujoco.mjtObj.mjOBJ_GEOM, name
            )
            if geom_id >= 0:
                return int(geom_id)
        return -1

    ball_geom_id = first_geom_id(("ball", "ball_geom"))
    boundary_mode = str(getattr(
        cfg, "ball_racket_contact_boundary_mode", "robot_dynamic"
    ))
    racket_geom_id = first_geom_id(
        (RACKET_CONTACT_PROXY_GEOM_NAME,)
        if boundary_mode == "fk_heavy_proxy_v1"
        else ("racket_rubber_fore", "racket")
    )
    pair_ids = tuple(
        pair_id
        for pair_id in range(model.npair)
        if {
            int(model.pair_geom1[pair_id]),
            int(model.pair_geom2[pair_id]),
        }
        == {ball_geom_id, racket_geom_id}
    )
    enabled = bool(getattr(cfg, "ball_racket_pair_override_enabled", False))
    if not enabled:
        return pair_ids
    if ball_geom_id < 0 or racket_geom_id < 0 or len(pair_ids) != 1:
        raise ValueError(
            "compiled ball-racket override requires exactly one explicit pair"
        )

    def vector(name: str, size: int) -> np.ndarray:
        value = np.asarray(tuple(getattr(cfg, name)), dtype=np.float64)
        if value.shape != (size,) or not np.all(np.isfinite(value)):
            raise ValueError(f"{name} must be a finite {size}-vector")
        return value

    solref = vector("ball_racket_pair_solref", 2)
    solreffriction = vector("ball_racket_pair_solreffriction", 2)
    solimp = vector("ball_racket_pair_solimp", 5)
    friction = vector("ball_racket_pair_friction", 5)
    margin_m = float(getattr(cfg, "ball_racket_pair_margin_m"))
    gap_m = float(getattr(cfg, "ball_racket_pair_gap_m"))
    condim = int(getattr(cfg, "ball_racket_pair_condim"))
    if solref[0] <= 0.0 or solref[1] <= 0.0:
        raise ValueError("ball-racket pair solref values must be positive")
    friction_tied = np.all(solreffriction == 0.0)
    friction_independent = np.all(solreffriction > 0.0)
    if not (friction_tied or friction_independent):
        raise ValueError(
            "pair solreffriction must be the zero sentinel or positive"
        )
    if not (
        0.0 < solimp[0] < solimp[1] < 1.0
        and solimp[2] > 0.0
        and 0.0 < solimp[3] < 1.0
        and solimp[4] >= 1.0
    ):
        raise ValueError("invalid ball-racket pair solimp contract")
    if np.any(friction < 0.0):
        raise ValueError("ball-racket pair friction must be non-negative")
    if (
        bool(getattr(cfg, "ball_racket_pair_tie_tangent_friction_dr", False))
        and not np.isclose(friction[0], friction[1], rtol=0.0, atol=1.0e-12)
    ):
        raise ValueError(
            "tied tangential friction DR requires equal nominal axes"
        )
    if not (
        np.isfinite([margin_m, gap_m]).all()
        and 0.0 <= gap_m <= margin_m
    ):
        raise ValueError("pair gap must satisfy 0 <= gap <= margin")
    if condim not in {1, 3, 4, 6}:
        raise ValueError("ball-racket pair condim must be 1, 3, 4, or 6")
    geometry = str(getattr(cfg, "ball_racket_collision_geometry"))
    if geometry == "finite_mesh16" and (margin_m != 0.0 or gap_m != 0.0):
        raise ValueError(
            "MJX finite_mesh16 requires exact-zero pair margin and gap"
        )
    pair_id = pair_ids[0]
    model.pair_solref[pair_id] = solref
    model.pair_solreffriction[pair_id] = solreffriction
    model.pair_solimp[pair_id] = solimp
    model.pair_friction[pair_id] = friction
    model.pair_margin[pair_id] = margin_m
    model.pair_gap[pair_id] = gap_m
    model.pair_dim[pair_id] = condim
    return pair_ids


def bounded_base_local_y_velocity_target_jax(
    ball_view_y: jax.Array,
    target_y: float,
    gain_s_inv: float,
    max_speed_m_s: float,
    deadband_m: float,
) -> jax.Array:
    """Return a bounded local-Y velocity that moves toward ``target_y``.

    The deadband deliberately leaves an already-centered ball with a zero
    lateral target.  This is a shaping target, not a safety limit: callers
    must continue to evaluate actual ball velocity for safety gates.
    """

    error = float(target_y) - ball_view_y
    outside_deadband = jnp.sign(error) * jnp.maximum(
        jnp.abs(error) - float(deadband_m), 0.0
    )
    return jnp.clip(
        float(gain_s_inv) * outside_deadband,
        -float(max_speed_m_s),
        float(max_speed_m_s),
    )


def bounded_apex_view_y_progress_jax(
    ball_view_y: jax.Array,
    apex_view_y: jax.Array,
    target_y: float,
    sigma_m: float,
    deadband_m: float,
) -> jax.Array:
    """Score signed improvement from contact local-Y to predicted apex local-Y.

    Positive values mean the outgoing trajectory moves toward the desired
    view center; negative values mean it moves farther away.  The bounded
    score prevents an off-center contact from buying unlimited lateral motion.
    """

    contact_excess = jnp.maximum(
        jnp.abs(ball_view_y - float(target_y)) - float(deadband_m), 0.0
    )
    apex_excess = jnp.maximum(
        jnp.abs(apex_view_y - float(target_y)) - float(deadband_m), 0.0
    )
    return jnp.clip(
        (contact_excess - apex_excess) / max(1e-6, float(sigma_m)),
        -1.0,
        1.0,
    )


def local_y_return_alignment_jax(
    target_velocity: jax.Array,
    observed_velocity: jax.Array,
) -> jax.Array:
    """Whether a measured local-Y velocity follows a nonzero requested return."""

    return (jnp.abs(target_velocity) > 1.0e-6) & (
        target_velocity * observed_velocity > 0.0
    )


def bounded_local_y_return_outcome_score_jax(
    target_velocity: jax.Array,
    observed_velocity: jax.Array,
    sigma_m_s: float,
) -> jax.Array:
    """Score the *measured* local-Y result of a requested return strike.

    The score is +1 at the bounded velocity target and smoothly reaches -1
    for a strongly wrong-direction or excessive-speed result.  A centered
    ball has no lateral target and receives zero credit, so this term cannot
    manufacture a lateral motion requirement in ordinary juggling states.
    """

    normalized_error = (observed_velocity - target_velocity) / max(
        1.0e-6, float(sigma_m_s)
    )
    matched_target_score = 2.0 * jnp.exp(-0.5 * normalized_error * normalized_error) - 1.0
    return jnp.where(jnp.abs(target_velocity) > 1.0e-6, matched_target_score, 0.0)


def apply_quadratic_ball_drag_jax(
    linear_velocity_m_s: jax.Array,
    drag_coefficient_m_inv: float,
    dt_s: float,
) -> jax.Array:
    """Apply one stable split step of ``dv/dt=-k||v||v``.

    The closed-form speed update keeps direction fixed over the substep and
    cannot flip velocity when the product ``k*||v||*dt`` is large.  A zero
    coefficient is exactly identity, preserving every historical profile.
    """

    coefficient = max(0.0, float(drag_coefficient_m_inv))
    if coefficient <= 0.0:
        return linear_velocity_m_s
    speed = jnp.linalg.norm(linear_velocity_m_s, axis=-1, keepdims=True)
    return linear_velocity_m_s / (
        1.0 + coefficient * speed * max(0.0, float(dt_s))
    )


def adaptive_reflected_velocity_target_jax(
    contact_position_m: jax.Array,
    target_position_xy_m: jax.Array,
    target_apex_z_m: jax.Array,
    gravity_m_s2: float,
    drag_coefficient_m_inv: float,
    adaptive_center_coefficient_m_inv: float,
) -> jax.Array:
    """Paper-derived adaptive desired outgoing velocity at a contact.

    This implements Eqs. (11)--(18) of Xu et al.: a quadratic-drag
    Center-Strategy direction is blended with the Vertical-Strategy using
    ``lambda(x)=x*exp(c*x)``.  Near the anchor the target is vertical; farther
    away it adds a smooth inward correction without making exact recentering
    the sole objective.
    """

    gravity = max(1.0e-6, abs(float(gravity_m_s2)))
    drag = max(0.0, float(drag_coefficient_m_inv))
    center_c = max(0.0, float(adaptive_center_coefficient_m_inv))
    apex_height = jnp.maximum(target_apex_z_m - contact_position_m[:, 2], 1.0e-4)
    desired_vz = jnp.sqrt(2.0 * gravity * apex_height)
    flight_time = 2.0 * desired_vz / gravity

    displacement_xy = target_position_xy_m - contact_position_m[:, :2]
    distance_xy = jnp.linalg.norm(displacement_xy, axis=-1)
    if drag > 0.0:
        center_vxy = (
            jnp.sign(displacement_xy)
            * jnp.expm1(drag * jnp.abs(displacement_xy))
            / (drag * jnp.maximum(flight_time[:, None], 1.0e-6))
        )
    else:
        center_vxy = displacement_xy / jnp.maximum(flight_time[:, None], 1.0e-6)

    vertical = jnp.concatenate(
        [jnp.zeros_like(center_vxy), desired_vz[:, None]], axis=-1
    )
    center = jnp.concatenate([center_vxy, desired_vz[:, None]], axis=-1)
    vertical_dir = vertical / jnp.maximum(
        jnp.linalg.norm(vertical, axis=-1, keepdims=True), 1.0e-6
    )
    center_dir = center / jnp.maximum(
        jnp.linalg.norm(center, axis=-1, keepdims=True), 1.0e-6
    )
    adaptive_weight = distance_xy * jnp.exp(center_c * distance_xy)
    blended = vertical_dir + adaptive_weight[:, None] * center_dir
    blended_dir = blended / jnp.maximum(
        jnp.linalg.norm(blended, axis=-1, keepdims=True), 1.0e-6
    )
    scale = desired_vz / jnp.maximum(blended_dir[:, 2], 1.0e-6)
    return blended_dir * scale[:, None]


def compose_hit_bonus_jax(
    hit_motion_quality_score: jax.Array,
    hit_quality: jax.Array,
    hit_count_credit: jax.Array,
    *,
    hit_reward_base: float,
    combo_quality_independent: bool,
    combo_motion_quality_independent: bool,
) -> jax.Array:
    """Compose contact-quality credit and survival/count credit.

    Historically ``hit_motion_quality_score`` multiplies the complete hit
    bonus, including the count-dependent combo term.  That makes a later hit
    carry a larger ball-motion gradient solely because it occurs later in the
    same rollout.  RMS, by contrast, gives every contact one sample and its
    bad tail in the warm-start policy is concentrated in hits 1--3.

    The optional split keeps the base contact credit motion-quality gated but
    makes combo credit a pure survival signal.  The older
    ``combo_quality_independent`` switch still controls whether contact
    centre/flatness quality applies to that survival signal.  Both switches
    default to false, preserving all historical profiles exactly.
    """

    base_credit = (
        hit_motion_quality_score * float(hit_reward_base) * hit_quality
    )
    combo_contact_quality = jnp.where(
        bool(combo_quality_independent), 1.0, hit_quality
    )
    combo_credit = hit_count_credit * combo_contact_quality
    return jnp.where(
        bool(combo_motion_quality_independent),
        base_credit + combo_credit,
        base_credit + hit_motion_quality_score * combo_credit,
    )


def select_post_hit_ball_latency_steps_jax(
    previous_steps: jax.Array,
    refresh: jax.Array,
    sample_available: jax.Array,
    hit_count: jax.Array,
    sampled_steps: jax.Array,
    sampled_active: jax.Array,
    *,
    min_confirmed_hits: int,
) -> jax.Array:
    """Apply extra ball-observation lag only to fresh post-hit samples.

    The caller supplies the Bernoulli decision and sampled delay so this
    transition remains small, JIT-friendly and directly unit-testable.  A new
    camera sample prior to the first confirmed hit always has zero injected
    delay; a non-refresh keeps the current sample's lag unchanged.
    """

    eligible = (
        refresh
        & sample_available
        & (hit_count >= int(min_confirmed_hits))
    )
    sampled = jnp.where(sampled_active, sampled_steps, 0).astype(jnp.int32)
    return jnp.where(
        eligible,
        sampled,
        jnp.where(refresh, 0, previous_steps),
    ).astype(jnp.int32)


def apply_ball_only_observation_latency_jax(
    raw_base_obs: jax.Array,
    delayed_base_obs: jax.Array,
    latency_steps: jax.Array,
    *,
    dt_s: float,
    age_clip_s: float,
    timestamp_consistent_age: bool = False,
    timestamp_consistent_active: jax.Array | None = None,
) -> jax.Array:
    """Replace only ball-derived actor features with a buffered observation.

    The legacy 50-D base layout puts ball position/velocity at 20:26, racket
    position at 26:29, relative ball/racket position at 32:35 and ball age at
    49.  Keeping every proprioceptive, racket and action-feedback feature
    current avoids turning a ball-camera robustness lesson into an unrelated
    whole-state latency experiment.
    """

    ball_pos = delayed_base_obs[:, 20:23]
    ball_vel = delayed_base_obs[:, 23:26]
    legacy_age_seconds = jnp.clip(
        raw_base_obs[:, 49] * float(age_clip_s)
        + latency_steps.astype(jnp.float32) * float(dt_s),
        0.0,
        float(age_clip_s),
    )
    if bool(timestamp_consistent_age):
        # ``delayed_base_obs`` was captured ``latency_steps`` control ticks
        # ago.  Its internal age is therefore the selected camera sample's
        # age at that buffered control tick; advance it to the current tick.
        # This differs materially from adding the control lag to the current
        # raw frame's age when the camera rate is below the control rate.
        buffered_age_seconds = jnp.clip(
            delayed_base_obs[:, 49] * float(age_clip_s)
            + latency_steps.astype(jnp.float32) * float(dt_s),
            0.0,
            float(age_clip_s),
        )
        if timestamp_consistent_active is None:
            age_seconds = buffered_age_seconds
        else:
            age_seconds = jnp.where(
                timestamp_consistent_active,
                buffered_age_seconds,
                legacy_age_seconds,
            )
    else:
        age_seconds = legacy_age_seconds
    output = raw_base_obs.at[:, 20:23].set(ball_pos)
    output = output.at[:, 23:26].set(ball_vel)
    output = output.at[:, 32:35].set(ball_pos - raw_base_obs[:, 26:29])
    return output.at[:, 49].set(
        age_seconds / max(1e-6, float(age_clip_s))
    )


def symmetric_target_score_jax(
    value: jax.Array,
    target: float | jax.Array,
    sigma: float,
) -> jax.Array:
    """Return a bounded two-sided score with slope on both sides of target."""

    normalized_error = (value - target) / max(1e-6, float(sigma))
    return jnp.exp(-0.5 * normalized_error * normalized_error)


def compose_hit_apex_target_reward_jax(
    target_score: jax.Array,
    motion_quality_score: jax.Array,
    weight: float,
    *,
    motion_quality_independent: bool,
) -> jax.Array:
    """Compose bounded apex credit while preserving the historical coupling."""

    quality_multiplier = jnp.where(
        bool(motion_quality_independent),
        jnp.ones_like(motion_quality_score),
        motion_quality_score,
    )
    return float(weight) * target_score * quality_multiplier


def joint_apex_lift_target_score_jax(
    predicted_apex_z: jax.Array,
    contact_ball_z: jax.Array,
    apex_target_z: float | jax.Array,
    apex_sigma_m: float,
    lift_target_m: float,
    lift_sigma_m: float,
) -> jax.Array:
    """Score absolute apex and contact-to-apex lift as one joint objective.

    The product is high only when both physical coordinates are correct.  It
    therefore cannot be maximized by raising the complete contact trajectory
    while retaining a low-amplitude flight, or by producing the right lift at
    an unsafe absolute height.
    """

    apex_score = symmetric_target_score_jax(
        predicted_apex_z,
        apex_target_z,
        apex_sigma_m,
    )
    lift_score = symmetric_target_score_jax(
        predicted_apex_z - contact_ball_z,
        lift_target_m,
        lift_sigma_m,
    )
    return apex_score * lift_score


def post_first_hit_alive_reward_jax(
    hit_count: jax.Array,
    weight: float,
) -> jax.Array:
    """Credit every live control tick after acquisition of the first hit.

    The default weight is zero at the configuration boundary, so all existing
    profiles retain their exact reward.  Unlike the historical post-hit
    recoverability reward, this term does not disappear while the ball is
    descending below the racket anchor; the episode therefore loses future
    credit whenever it terminates early.
    """

    return float(weight) * (hit_count > 0).astype(jnp.float32)


def full_episode_completion_reward_jax(
    truncated: jax.Array,
    weight: float,
    *,
    hit_count: jax.Array | None = None,
    min_hits: int = 0,
) -> jax.Array:
    """Pay a full-horizon event, optionally gated by counted contacts.

    ``min_hits=0`` preserves the historical completion reward exactly.  A
    positive threshold prevents a policy from collecting completion credit by
    merely keeping a never-acquired ball episode alive.
    """

    eligible = truncated
    if int(min_hits) > 0:
        if hit_count is None:
            raise ValueError("hit_count is required when min_hits is positive")
        eligible = eligible & (hit_count >= int(min_hits))
    return float(weight) * eligible.astype(jnp.float32)


def early_termination_remaining_horizon_penalty_jax(
    terminated: jax.Array,
    step_count: jax.Array,
    *,
    episode_limit: int | jax.Array,
    weight: float,
) -> jax.Array:
    """Charge an immediate loss proportional to unfinished episode time.

    This is opt-in so historical profiles remain exact.  Unlike a sparse
    horizon-completion event, the signal is emitted at the actual failure and
    can therefore be assigned by finite-lambda GAE to the preceding causal
    contact cycle.  Later failures receive a smaller loss, aligning the
    reward with both full-episode probability and expected episode length.
    """

    limit = jnp.maximum(1.0, jnp.asarray(episode_limit, dtype=jnp.float32))
    remaining_fraction = jnp.clip(
        (limit - step_count.astype(jnp.float32)) / limit,
        0.0,
        1.0,
    )
    return (
        -float(weight)
        * remaining_fraction
        * terminated.astype(jnp.float32)
    )


def failure_only_termination_mask_jax(
    terminated: jax.Array,
    task_success: jax.Array,
) -> jax.Array:
    """Remove deliberate task-success termination from failure penalties."""

    return jnp.asarray(terminated, dtype=jnp.bool_) & ~jnp.asarray(
        task_success, dtype=jnp.bool_
    )


def fixed_contact_racket_workspace_termination_mask_jax(
    done_terms: dict[str, jax.Array],
) -> jax.Array:
    """Combine the versioned fixed-contact racket XYZ workspace failures."""

    required = (
        "racket_x_out_of_bounds",
        "racket_y_out_of_bounds",
        "racket_z_out_of_bounds",
    )
    missing = [name for name in required if name not in done_terms]
    if missing:
        raise ValueError(
            "fixed-contact workspace termination terms are missing: "
            + ", ".join(missing)
        )
    result = jnp.asarray(done_terms[required[0]], dtype=jnp.bool_)
    for name in required[1:]:
        result = result | jnp.asarray(done_terms[name], dtype=jnp.bool_)
    return result


def aggregate_termination_terms_jax(
    done_terms: dict[str, jax.Array],
    *,
    excluded_keys: tuple[str, ...] = (),
) -> jax.Array:
    """OR termination terms while preserving explicitly diagnostic terms."""

    if not done_terms:
        raise ValueError("termination terms must not be empty")
    excluded = frozenset(excluded_keys)
    included = [
        jnp.asarray(value, dtype=jnp.bool_)
        for name, value in done_terms.items()
        if name not in excluded
    ]
    if not included:
        exemplar = next(iter(done_terms.values()))
        return jnp.zeros_like(exemplar, dtype=jnp.bool_)
    result = included[0]
    for value in included[1:]:
        result = result | value
    return result


def full_episode_joint_height_reward_jax(
    truncated: jax.Array,
    hit_count: jax.Array,
    mean_apex_abs_z_m: jax.Array,
    mean_apex_lift_m: jax.Array,
    *,
    apex_target_m: float,
    apex_sigma_m: float,
    lift_target_m: float,
    lift_sigma_m: float,
    min_hits: int,
    max_hits: int,
    weight: float,
) -> jax.Array:
    """Reward only full episodes that jointly meet count and height intent."""

    count_ok = (hit_count >= int(min_hits)) & (hit_count <= int(max_hits))
    apex_score = symmetric_target_score_jax(
        mean_apex_abs_z_m,
        float(apex_target_m),
        float(apex_sigma_m),
    )
    lift_score = symmetric_target_score_jax(
        mean_apex_lift_m,
        float(lift_target_m),
        float(lift_sigma_m),
    )
    return (
        float(weight)
        * truncated.astype(jnp.float32)
        * count_ok.astype(jnp.float32)
        * apex_score
        * lift_score
    )


def select_hit_contact_heights_jax(
    confirmation_ball_z: jax.Array,
    confirmation_racket_z: jax.Array,
    contact_edge_ball_z: jax.Array,
    contact_edge_racket_z: jax.Array,
    mode: str,
) -> tuple[jax.Array, jax.Array]:
    """Select legacy confirmation or cached physical-edge hit heights."""

    normalized = str(mode).lower()
    if normalized == "confirmation":
        return confirmation_ball_z, confirmation_racket_z
    if normalized == "contact_edge":
        return contact_edge_ball_z, contact_edge_racket_z
    raise ValueError(
        "hit contact height mode must be 'confirmation' or 'contact_edge', "
        f"got {mode!r}"
    )


def select_cadence_interval_and_masks_jax(
    raw_interval_s: jax.Array,
    counted_interval_s: jax.Array,
    has_previous_raw_hit: jax.Array,
    has_previous_counted_hit: jax.Array,
    counted_hit: jax.Array,
    rewardable_hit: jax.Array,
    *,
    use_counted_interval: bool,
    penalty_after_reward_cap: bool,
) -> tuple[jax.Array, jax.Array, jax.Array]:
    """Select cadence timing while preserving the historical default masks."""

    interval_s = counted_interval_s if use_counted_interval else raw_interval_s
    has_previous = (
        has_previous_counted_hit
        if use_counted_interval
        else has_previous_raw_hit
    )
    reward_eligible = counted_hit & rewardable_hit & has_previous
    penalty_eligible = (
        counted_hit
        & has_previous
        & (rewardable_hit | bool(penalty_after_reward_cap))
    )
    return interval_s, reward_eligible, penalty_eligible


